import { useState } from 'react';
import { JxButton, JxDrawer } from '@jinx-ui/react';

type NavKey = 'projects' | 'team' | 'settings' | 'logout';

const ITEMS: { key: NavKey; label: string }[] = [
  { key: 'projects', label: 'Проекты' },
  { key: 'team', label: 'Команда' },
  { key: 'settings', label: 'Настройки' },
];

export default function NavigationMenu({
  onNavigate,
}: {
  onNavigate: (key: NavKey) => void;
}) {
  const [open, setOpen] = useState(false);

  const select = (key: NavKey) => {
    onNavigate(key);
    setOpen(false);
  };

  return (
    <>
      <JxButton variant="primary" onClick={() => setOpen(true)}>
        Меню
      </JxButton>

      <JxDrawer
        open={open}
        onOpenChange={setOpen}
        side="left"
        title="Навигация"
      >
        <nav
          aria-label="Основная навигация"
          style={{
            display: 'flex',
            flexDirection: 'column',
            gap: 'var(--jx-space-1)',
          }}
        >
          {ITEMS.map((item) => (
            <JxButton
              key={item.key}
              variant="ghost"
              onClick={() => select(item.key)}
              style={{ justifyContent: 'flex-start', width: '100%' }}
            >
              {item.label}
            </JxButton>
          ))}

          <hr
            style={{
              width: '100%',
              border: 'none',
              borderTop: '1px solid var(--jx-color-border)',
